WITH row AS (INSERT INTO zc_private.discord_delivery(guild_id,event_id,channel_id,message_id,status,last_error) VALUES($1,$2,$3,$4,$5,$6) ON CONFLICT(guild_id,event_id) DO UPDATE SET channel_id=excluded.channel_id, message_id=excluded.message_id,status=excluded.status,last_error=excluded.last_error,date_updated=clock_timestamp() RETURNING *) SELECT jsonb_build_object('guildId',guild_id::text,'eventId',event_id::text,'channelId', channel_id::text,'messageId',CASE WHEN message_id IS NULL THEN NULL ELSE to_jsonb(message_id::text) END, 'status',status,'lastError',last_error,'dateUpdated',to_char(date_updated AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')) AS value FROM row
